    // Sky textures
    private static Identifier tex(String body) {
        return InterplanetaryStuff.id("textures/environment/bodies/" + body + ".png");
    }

    private static final Identifier SATURN_RINGS = InterplanetaryStuff.id("textures/environment/saturn_rings.png");
    private static final Identifier URANUS_RINGS = InterplanetaryStuff.id("textures/environment/uranus_rings.png");

    private static SkyObject saturn(float size, float azimuth, float elevation, float ringTilt) {
        return SkyObject.fixed(tex("saturn"), size, azimuth, elevation)
                .withRing(new SkyObject.Ring(SATURN_RINGS, 2.3F, ringTilt, 8.0F, 1.0F));
    }

    private static SkyObject uranus(float size, float azimuth, float elevation) {
        return SkyObject.fixed(tex("uranus"), size, azimuth, elevation)
                .withRing(new SkyObject.Ring(URANUS_RINGS, 2.0F, 10.0F, 78.0F, 0.55F));
    }

